with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('skabe sig', 'phrase', '609a0cb6-bd56-5174-a909-1b76af198901', 1, 'verb', null, 'to make a fuss, to act up', 'Hun skaber sig altid når hun skal i seng.', 'She always makes a fuss when she has to go to bed.'), ('køre sammen', 'phrase', '2ad026ac-3f74-569c-9bec-adfa2bb6af5c', 1, 'verb', null, 'to collide (of vehicles)', 'Bussen og lastbilen kørte sammen i krydset.', 'The bus and the truck collided at the intersection.'), ('køre ud', 'phrase', 'adfd3dd7-52e3-5851-8ac3-c9049ae29b51', 1, 'verb', null, 'to drive out (from a garage, onto a road)', 'Bilen kører ud fra garagen hver morgen.', 'The car drives out of the garage every morning.'), ('køre ud', 'phrase', '66a3069b-ac8a-5394-90bb-36b3ebf05a1b', 2, 'verb', null, 'to deliver (goods)', 'Vi kører ud med varer til kunderne om eftermiddagen.', 'We deliver goods to customers in the afternoon.'), ('følge op', 'phrase', '408d00df-2031-51ad-baa4-3428c1043699', 1, 'verb', null, 'to follow up', 'Læreren fulgte op på elevernes spørgsmål efter timen.', 'The teacher followed up on the students'' questions after the lesson.'), ('give sig til kende', 'phrase', '04c2deb7-8fff-57d6-bb5c-c9d1d102188a', 1, 'verb', null, 'to make itself known (to manifest)', 'Sygdommen gav sig til kende med feber og træthed.', 'The illness manifested itself with fever and fatigue.'), ('slå igen', 'phrase', 'bc71e3e7-749d-59e1-8ad2-ee1becaec1e2', 1, 'verb', null, 'to hit back', 'Han slog igen, da de drillede ham.', 'He hit back when they teased him.'), ('slå ud', 'phrase', '26b71214-6253-5f85-8273-b289a37bc009', 1, 'verb', null, 'to bloom (of flowers)', 'Roserne slog ud i haven i går.', 'The roses bloomed in the garden yesterday.'), ('falde for', 'phrase', '2bac3c33-f362-5d63-8ddd-24ea85cdc53c', 1, 'verb', null, 'to fall for (someone)', 'Jeg faldt for hende med det samme.', 'I fell for her immediately.'), ('falde for', 'phrase', '2f6b6afe-e25d-59a1-979f-b77560087ec9', 2, 'verb', null, 'to fall for (a trick)', 'Han falder for den samme undskyldning hver gang.', 'He falls for the same excuse every time.'), ('falde over', 'phrase', '2ebbbb1b-fabe-5e94-ab17-22593c655060', 1, 'verb', null, 'to stumble upon (something)', 'Hun faldt over en gammel bog på loftet.', 'She stumbled upon an old book in the attic.'), ('inden under', 'phrase', '13801b12-b403-5798-bf21-8399d3e5ba26', 1, 'preposition', null, 'underneath', 'Katten gemmer sig inden under sofaen.', 'The cat hides under the sofa.'), ('nå frem til', 'phrase', '9e05da9d-59c2-5969-9588-dbc9c83ea1e2', 1, 'verb', null, 'to arrive at (a conclusion, agreement)', 'Vi nåede frem til en løsning efter lang tids diskussion.', 'We arrived at a solution after a long discussion.'), ('lyde på', 'phrase', '543329ed-7ccb-5618-8fa2-78aa2ca0417b', 1, 'verb', null, 'to amount to (a sum, bill)', 'Regningen lød på tre hundrede kroner.', 'The bill amounted to three hundred kroner.'), ('stige ned', 'phrase', '2137ed53-b071-57af-a74e-93aab768d439', 1, 'verb', null, 'to descend (go down)', 'Han steg ned ad trappen med en tung kuffert.', 'He descended the stairs with a heavy suitcase.'), ('betale af', 'phrase', '0b53614f-d31d-5b22-95db-7112a34b22a3', 1, 'verb', null, 'to pay off (a debt)', 'Jeg betaler af på mit lån hver måned.', 'I pay off my loan every month.'), ('køre videre', 'phrase', '4f0156c3-964d-52e5-92ae-48b4abd74f16', 1, 'verb', null, 'to drive on', 'Vi kører videre mod nord efter frokost.', 'We drive on north after lunch.'), ('forsøge sig', 'phrase', 'add80b5a-7fd4-595a-96e7-a51966e013a7', 1, 'verb', null, 'to try one''s hand (at something)', 'Hun vil gerne forsøge sig som forfatter.', 'She would like to try her hand at being a writer.'), ('gøre det kort', 'phrase', 'f455e403-2a2c-5ac1-a6c6-fe0b73fd6e3c', 1, 'verb', null, 'to be brief', 'Jeg gør det kort, fordi jeg har travlt.', 'I''ll be brief because I''m busy.'), ('ligge stille', 'phrase', 'ffdb061c-f785-542b-ad6c-99c376f8e059', 1, 'verb', null, 'to lie still', 'Hunden ligger stille på gulvet.', 'The dog lies still on the floor.'), ('sidde stille', 'phrase', '8e3b74e1-aa34-5d53-980b-c56135024ffe', 1, 'verb', null, 'to sit still (without moving)', 'Børnene sad stille og lyttede til historien.', 'The children sat quietly and listened to the story.'), ('bag på', 'phrase', '62dcf3cf-2cdf-5881-9a12-36fa87b820c2', 1, 'preposition', null, 'on the back of', 'Der er en plet bag på skjorten.', 'There is a stain on the back of the shirt.'), ('stå bag', 'phrase', 'eeea1fa8-ecf1-5e01-8c3f-3ae3e40543a1', 1, 'verb', null, 'to support (someone)', 'Hun står bag sin ven i svære tider.', 'She stands behind her friend in difficult times.'), ('stå bag', 'phrase', '41d53e58-5f1d-5be8-a3d0-1c9b71a64365', 2, 'verb', null, 'to be behind (something, as the cause)', 'Politiet tror, at en gruppe står bag tyveriet.', 'The police believe that a group is behind the theft.'), ('trække sig ud', 'phrase', '8f5d7ad9-bfbe-5c71-8c6c-ee2795bc03c7', 1, 'verb', null, 'to withdraw (from participation)', 'Virksomheden trak sig ud af samarbejdet i sidste uge.', 'The company withdrew from the collaboration last week.'), ('trække sig ud', 'phrase', '56910bd9-79a4-59c2-880b-2c2bfc6cb054', 2, 'verb', null, 'to drag on (about time)', 'Mødet trak sig ud og varede over tre timer.', 'The meeting dragged on and lasted over three hours.'), ('holde fast i', 'phrase', '5bda9fd2-0d4a-55e7-8f18-53852dfafab6', 1, 'verb', null, 'to stick to (an opinion, decision)', 'Han holdt fast i sin mening under mødet.', 'He stuck to his opinion during the meeting.'), ('køre fast', 'phrase', '1bd66e81-9d1e-5e83-8dc6-07a7e32d9299', 1, 'verb', null, 'to get stuck (vehicle)', 'Bilen kørte fast i mudderet.', 'The car got stuck in the mud.'), ('køre fast', 'phrase', '1503d90f-27f4-53b6-b150-1b504f1d8169', 2, 'verb', null, 'to get stuck (person, conversation)', 'Mødet kører fast i detaljer.', 'The meeting gets bogged down in details.'), ('sætte sig fast', 'phrase', '053fe92f-518a-5722-a1bd-4a77fa4936b6', 1, 'verb', null, 'to get stuck', 'Bilen satte sig fast i mudderet.', 'The car got stuck in the mud.'), ('bo for sig selv', 'phrase', '81ece2d8-44ab-56f1-85fe-b2c7d65d481b', 1, 'verb', null, 'to live on one''s own', 'Min datter bor for sig selv i København.', 'My daughter lives by herself in Copenhagen.'), ('bo sammen', 'phrase', 'a03dbb42-b3fd-54da-a220-74b39e5f7699', 1, 'verb', null, 'to live together (with someone)', 'De bor sammen i en lille lejlighed.', 'They live together in a small apartment.'), ('være til hjælp', 'phrase', '1d05f67f-31a6-553a-bac0-82d734f96c31', 1, 'verb', null, 'to be helpful', 'Hans råd var til hjælp for mig.', 'His counsel was helpful to me.'), ('give hånd', 'phrase', '64c31d20-fc48-5106-a960-cba80f00ba3b', 1, 'verb', null, 'to shake hands', 'De gav hånd, da de mødtes.', 'They shook hands when they met.'), ('flytte sammen', 'phrase', 'f8c10d9c-fd97-5f55-af01-2f74c8731c0d', 1, 'verb', null, 'to move in together', 'De flyttede sammen efter et halvt år.', 'They moved in together after six months.'), ('få til opgave', 'phrase', '3d54cb47-b993-5d17-b8e5-ccaa3ec6588c', 1, 'verb', null, 'to be given the task', 'Hun fik til opgave at rydde op på værelset.', 'She was given the task of cleaning up the room.'), ('ændre ved', 'phrase', '9d8838af-a4d3-51df-877f-312a782737d4', 1, 'verb', null, 'to change (something)', 'De ændrede ved aftalen i sidste øjeblik.', 'They changed the agreement at the last minute.'), ('rette op på', 'phrase', 'bab5047f-25a8-5dde-91df-cc149fa67766', 1, 'verb', null, 'to correct (a mistake or situation)', 'Han rettede op på fejlen med det samme.', 'He corrected the mistake immediately.'), ('rette sig efter', 'phrase', 'c31c867c-2a03-54da-b2c2-1884f4718f64', 1, 'verb', null, 'to comply with, to follow', 'Jeg retter mig efter de nye regler på arbejdet.', 'I follow the new rules at work.'), ('rette sig mod', 'phrase', 'fd8deddb-1edd-5dd7-b434-487afa0cd031', 1, 'verb', null, 'to be aimed at', 'Kritikken retter sig mod regeringens plan.', 'The criticism is directed at the government''s plan.'), ('rette sig mod', 'phrase', 'dddf40df-840d-5567-90a0-00abc9b7928a', 2, 'verb', null, 'to address (someone)', 'Spørgsmålet retter sig mod alle forældre.', 'The question is aimed at all parents.'), ('vende sig til', 'phrase', '21c13d50-4aaa-5a43-a9a6-75e279974c31', 1, 'verb', null, 'to get used (to something)', 'Jeg vender mig til den nye rutine.', 'I get used to the new routine.'), ('have øje for', 'phrase', 'a77ae29d-e718-5178-93e2-fb47ec6d4868', 1, 'verb', null, 'to notice, to have an eye for', 'Hun har øje for detaljerne i maleriet.', 'She has an eye for the details in the painting.'), ('være længe om', 'phrase', '3047812d-0f1c-51bc-ab3a-70224160b450', 1, 'verb', null, 'to take a long time (doing sth.)', 'Han er længe om at spise morgenmad.', 'He takes a long time to eat breakfast.'), ('åbne sig', 'phrase', '208e04e9-6c57-5313-9982-b1e09946bef3', 1, 'verb', null, 'to open (itself, of a door, window)', 'Døren åbnede sig langsomt.', 'The door opened slowly.'), ('åbne sig', 'phrase', '9696c790-01d0-531f-b6d7-7b0bdac4699e', 2, 'verb', null, 'to open up (share feelings)', 'Hun åbner sig aldrig for fremmede.', 'She never opens up to strangers.'), ('se igennem', 'phrase', 'cd1a3c7c-d8b5-52fe-8811-863df9ec977e', 1, 'verb', null, 'to look through (check briefly)', 'Jeg ser igennem dokumenterne inden mødet.', 'I look through the documents before the meeting.'), ('se igennem', 'phrase', '79be4513-986e-587b-8346-4453ebeb6cfc', 2, 'verb', null, 'to look through (search)', 'Hun så igennem bunken for at finde kvitteringen.', 'She looked through the pile to find the receipt.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0012' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
